WITH filtered AS (SELECT *, UPPER(firmware) AS firmware_upper FROM device_readings WHERE reading_ts >= DATE '2025-09-01'), gaps AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) + INTERVAL 30 MINUTES THEN 1 ELSE 0 END AS session_start_flag FROM filtered), sessions_device_readings AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM gaps) SELECT DATE_TRUNC('DAY', reading_ts) AS activity_day, CASE WHEN status_bits >= 12 THEN 'LARGE' ELSE 'SMALL' END AS status_bits_tier, PERCENTILE_APPROX(temp_c, ARRAY(0.25, 0.5, 0.75)) AS temp_c_quartiles, SUM(CASE WHEN device_code = 'DV-01' THEN temp_c ELSE 0 END) AS dv_01_temp_c FROM sessions_device_readings GROUP BY GROUPING SETS ((DATE_TRUNC('DAY', reading_ts), CASE WHEN status_bits >= 12 THEN 'LARGE' ELSE 'SMALL' END), (DATE_TRUNC('DAY', reading_ts)), ()) ORDER BY status_bits_tier DESC
